MODULE INI_SPEC_DIST_ARGS_INFO_MOD

USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT

IMPLICIT NONE

PRIVATE
PUBLIC :: ARGS_INFO

! Shapes of the array arguments to INI_SPEC_DIST
TYPE, BIND(C) :: ARGS_INFO
  INTEGER(KIND=C_INT) :: IKASM0_SHAPE(1)
  INTEGER(KIND=C_INT) :: IKPROCM_SHAPE(1)
  INTEGER(KIND=C_INT) :: IKUMPP_SHAPE(1)
  INTEGER(KIND=C_INT) :: IKPOSSP_SHAPE(1)
  INTEGER(KIND=C_INT) :: IKMYMS_SHAPE(1)
  INTEGER(KIND=C_INT) :: IKPTRMS_SHAPE(1)
  INTEGER(KIND=C_INT) :: IKALLMS_SHAPE(1)
END TYPE ARGS_INFO

END MODULE INI_SPEC_DIST_ARGS_INFO_MOD

SUBROUTINE INI_SPEC_DIST(KSMAX, KTMAX, KPRTRW, KMYSETW, KASM0, KSPOLEGL, KPROCM, KUMPP, KSPEC, &
  &                      KSPEC2, KSPEC2MX, KPOSSP, KMYMS, KPTRMS, KALLMS)

USE PARKIND1,                    ONLY: JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_PTR, C_LOC, C_NULL_PTR
USE INI_SPEC_DIST_ARGS_INFO_MOD, ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE INI_SPEC_DIST_CPP_BINDING(ARGS, KSMAX, KTMAX, KPRTRW, KMYSETW, KSPOLEGL, KSPEC, KSPEC2, &
  &                                  KSPEC2MX, KASM0, KPROCM, KUMPP, KPOSSP, KMYMS, KPTRMS, KALLMS) &
  &                                  BIND(C, NAME="ini_spec_dist")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_PTR
  USE INI_SPEC_DIST_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KSMAX
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KTMAX
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KPRTRW
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KMYSETW
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KSPOLEGL
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KSPEC
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KSPEC2
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KSPEC2MX
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(OUT) :: KASM0(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(OUT) :: KPROCM(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(OUT) :: KUMPP(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(OUT) :: KPOSSP(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(OUT) :: KMYMS(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(OUT) :: KPTRMS(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(OUT) :: KALLMS(*)
END SUBROUTINE INI_SPEC_DIST_CPP_BINDING
END INTERFACE

INTEGER(KIND=JPIM),           INTENT(IN)  :: KSMAX
INTEGER(KIND=JPIM),           INTENT(IN)  :: KTMAX
INTEGER(KIND=JPIM),           INTENT(IN)  :: KPRTRW
INTEGER(KIND=JPIM),           INTENT(IN)  :: KMYSETW
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KSPEC
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KSPEC2
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KSPEC2MX
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KSPOLEGL
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KASM0(0:KSMAX)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KPROCM(0:KSMAX)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KUMPP(KPRTRW)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KPOSSP(KPRTRW+1)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KMYMS(KSMAX+1)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KPTRMS(KPRTRW)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KALLMS(KSMAX+1)

TYPE(ARGS_INFO) :: ARGS

! C-interoperable handles for the optional output scalars. A null C pointer indicates the argument
! was not present in the Fortran call; otherwise the pointer targets a local temporary which the
! C++ layer writes into and which is copied back after the call.
TYPE(C_PTR) :: KSPOLEGL_PTR, KSPEC_PTR, KSPEC2_PTR, KSPEC2MX_PTR
INTEGER(KIND=C_INT), TARGET :: ISPOLEGL, ISPEC, ISPEC2, ISPEC2MX

IF (PRESENT(KASM0)) THEN
  ARGS%IKASM0_SHAPE = SHAPE(KASM0, KIND=C_INT)
ELSE
  ARGS%IKASM0_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(KPROCM)) THEN
  ARGS%IKPROCM_SHAPE = SHAPE(KPROCM, KIND=C_INT)
ELSE
  ARGS%IKPROCM_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(KUMPP)) THEN
  ARGS%IKUMPP_SHAPE = SHAPE(KUMPP, KIND=C_INT)
ELSE
  ARGS%IKUMPP_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(KPOSSP)) THEN
  ARGS%IKPOSSP_SHAPE = SHAPE(KPOSSP, KIND=C_INT)
ELSE
  ARGS%IKPOSSP_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(KMYMS)) THEN
  ARGS%IKMYMS_SHAPE = SHAPE(KMYMS, KIND=C_INT)
ELSE
  ARGS%IKMYMS_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(KPTRMS)) THEN
  ARGS%IKPTRMS_SHAPE = SHAPE(KPTRMS, KIND=C_INT)
ELSE
  ARGS%IKPTRMS_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(KALLMS)) THEN
  ARGS%IKALLMS_SHAPE = SHAPE(KALLMS, KIND=C_INT)
ELSE
  ARGS%IKALLMS_SHAPE = 0_C_INT
ENDIF

IF (PRESENT(KSPOLEGL)) THEN
  KSPOLEGL_PTR = C_LOC(ISPOLEGL)
ELSE
  KSPOLEGL_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KSPEC)) THEN
  KSPEC_PTR = C_LOC(ISPEC)
ELSE
  KSPEC_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KSPEC2)) THEN
  KSPEC2_PTR = C_LOC(ISPEC2)
ELSE
  KSPEC2_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KSPEC2MX)) THEN
  KSPEC2MX_PTR = C_LOC(ISPEC2MX)
ELSE
  KSPEC2MX_PTR = C_NULL_PTR
ENDIF

CALL INI_SPEC_DIST_CPP_BINDING(ARGS, KSMAX, KTMAX, KPRTRW, KMYSETW, KSPOLEGL_PTR, KSPEC_PTR, &
  &                            KSPEC2_PTR, KSPEC2MX_PTR, KASM0=KASM0, KPROCM=KPROCM, KUMPP=KUMPP, &
  &                            KPOSSP=KPOSSP, KMYMS=KMYMS, KPTRMS=KPTRMS, KALLMS=KALLMS)

IF (PRESENT(KSPOLEGL)) KSPOLEGL = ISPOLEGL
IF (PRESENT(KSPEC))    KSPEC = ISPEC
IF (PRESENT(KSPEC2))   KSPEC2 = ISPEC2
IF (PRESENT(KSPEC2MX)) KSPEC2MX = ISPEC2MX

END SUBROUTINE INI_SPEC_DIST
